using System.Data;using System.Data.Common;using AiCare.Application;using AiCare.Domain;using AiCare.Infrastructure;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AiCare.Api;
[ApiController][Authorize(Policy="Phase1User")][Route("api/phase1/workforce-governance")]
public sealed class WorkforceGovernanceController(CareDbContext db,ITenantContext tenant,ICurrentUserContext user):ControllerBase
{
 [HttpGet("care-workers/{workerId:guid}")]public async Task<IActionResult> Workspace(Guid workerId,CancellationToken t){if(!CanRead(workerId)||!await Worker(workerId,t))return NotFound();var restrictions=await Rows("select id,restriction_type,skill,status,reason,evidence_reference,starts_at,ends_at,approved_by from worker_assignment_restrictions where care_worker_id=@worker and organization_id=@organization and branch_id=@branch order by created_at desc",workerId,t);var medication=await Rows("select id,status,scope,evidence_reference,authorized_at,expires_at,authorized_by,reason from worker_medication_authorizations where care_worker_id=@worker and organization_id=@organization and branch_id=@branch order by created_at desc",workerId,t);var policies=await Rows("select p.id,p.title,p.version,p.content_reference,p.published_at,p.requires_acknowledgement,a.acknowledged_at,a.evidence_reference from workforce_policies p left join workforce_policy_acknowledgements a on a.policy_id=p.id and a.care_worker_id=@worker where p.organization_id=@organization and p.active=true and (p.branch_id is null or p.branch_id=@branch) order by p.published_at desc",workerId,t);var cases=user.IsCareWorker?new List<Dictionary<string,object?>>():await Rows("select id,case_type,status,summary,owner,outcome,evidence_reference,opened_at,closed_at from worker_employee_relations_cases where care_worker_id=@worker and organization_id=@organization and branch_id=@branch order by opened_at desc",workerId,t);var wellbeing=await Rows("select id,recorded_at,category,summary,action,owner,review_due,status,evidence_reference from worker_wellbeing_records where care_worker_id=@worker and organization_id=@organization and branch_id=@branch order by recorded_at desc",workerId,t);var requests=await Rows("select id,request_type,starts_at,ends_at,detail,status,submitted_at,submitted_by,decision,decided_at,decided_by from worker_self_service_requests where care_worker_id=@worker and organization_id=@organization and branch_id=@branch order by submitted_at desc",workerId,t);return Ok(new{careWorkerId=workerId,restrictions,medicationAuthorizations=medication,policies,employeeRelations=cases,wellbeing,requests,alerts=Alerts(restrictions,medication,policies,wellbeing)});}
 [HttpPost("care-workers/{workerId:guid}/restrictions")][Authorize(Roles="CareManager,Administrator")]public async Task<IActionResult> Restrict(Guid workerId,RestrictionRequest request,CancellationToken t){if(!await Worker(workerId,t))return NotFound();if(request.RestrictionType is not("Skill" or "Duty" or "Medication")||string.IsNullOrWhiteSpace(request.Reason)||string.IsNullOrWhiteSpace(request.EvidenceReference)||request.EndsAt<=request.StartsAt)return BadRequest(new{message="Type, reason, evidence and a valid period are required."});var id=Guid.NewGuid();await Exec("insert into worker_assignment_restrictions(id,care_worker_id,organization_id,branch_id,restriction_type,skill,status,reason,evidence_reference,starts_at,ends_at,approved_by) values(@id,@worker,@organization,@branch,@type,@skill,'Active',@reason,@evidence,@starts,@ends,@actor)",workerId,c=>{Add(c,"id",id);Add(c,"type",request.RestrictionType);Add(c,"skill",request.Skill);Add(c,"reason",request.Reason);Add(c,"evidence",request.EvidenceReference);Add(c,"starts",request.StartsAt);Add(c,"ends",request.EndsAt);},t);await Audit("workforce.restriction_created","WorkerRestriction",id,t);return Created("",new{id});}
 [HttpPost("care-workers/{workerId:guid}/medication-authorization")][Authorize(Roles="CareManager,Administrator")]public async Task<IActionResult> Medication(Guid workerId,MedicationAuthorizationRequest request,CancellationToken t){if(!await Worker(workerId,t))return NotFound();if(request.Status is not("Authorized" or "Suspended" or "Revoked")||string.IsNullOrWhiteSpace(request.EvidenceReference)||request.Status!="Authorized"&&string.IsNullOrWhiteSpace(request.Reason))return BadRequest(new{message="Status, evidence and a reason for suspension/revocation are required."});if(request.Status=="Authorized"&&!await CurrentCompetency(workerId,"Medication administration",t))return Conflict(new{message="Current medication-administration competency is required before authorization."});var id=Guid.NewGuid();await Exec("insert into worker_medication_authorizations(id,care_worker_id,organization_id,branch_id,status,scope,evidence_reference,authorized_at,expires_at,authorized_by,reason) values(@id,@worker,@organization,@branch,@status,@scope,@evidence,now(),@expires,@actor,@reason)",workerId,c=>{Add(c,"id",id);Add(c,"status",request.Status);Add(c,"scope",request.Scope);Add(c,"evidence",request.EvidenceReference);Add(c,"expires",request.ExpiresAt);Add(c,"reason",request.Reason);},t);await Audit("workforce.medication_authorization_recorded","MedicationAuthorization",id,t);return Created("",new{id});}
 [HttpPost("policies")][Authorize(Roles="CareManager,Administrator")]public async Task<IActionResult> Policy(PolicyRequest request,CancellationToken t){if(string.IsNullOrWhiteSpace(request.Title)||string.IsNullOrWhiteSpace(request.Version)||string.IsNullOrWhiteSpace(request.ContentReference))return BadRequest(new{message="Title, version and content reference are required."});var id=Guid.NewGuid();try{await Exec("insert into workforce_policies(id,organization_id,branch_id,title,version,content_reference,published_at,published_by,requires_acknowledgement,active) values(@id,@organization,@policyBranch,@title,@version,@content,now(),@actor,@required,true)",Guid.Empty,c=>{Add(c,"id",id);Add(c,"policyBranch",request.OrganizationWide?null:tenant.BranchId??TenantDefaults.BranchId);Add(c,"title",request.Title);Add(c,"version",request.Version);Add(c,"content",request.ContentReference);Add(c,"required",request.RequiresAcknowledgement);},t);}catch(DbException){return Conflict(new{message="This policy version already exists."});}await Audit("workforce.policy_published","WorkforcePolicy",id,t);return Created("",new{id});}
 [HttpPost("care-workers/{workerId:guid}/policies/{policyId:guid}/acknowledge")]public async Task<IActionResult> Acknowledge(Guid workerId,Guid policyId,AcknowledgeRequest request,CancellationToken t){if(!CanRead(workerId)||!await Worker(workerId,t))return NotFound();if(user.IsCareWorker&&user.CareWorkerId!=workerId)return Forbid();if(string.IsNullOrWhiteSpace(request.EvidenceReference))return BadRequest(new{message="Acknowledgement evidence is required."});var policy=await Exists("select exists(select 1 from workforce_policies where id=@id and organization_id=@organization and active=true and (branch_id is null or branch_id=@branch))",workerId,t,c=>Add(c,"id",policyId));if(!policy)return NotFound();try{var id=Guid.NewGuid();await Exec("insert into workforce_policy_acknowledgements(id,policy_id,care_worker_id,organization_id,acknowledged_at,acknowledged_by,evidence_reference) values(@id,@policy,@worker,@organization,now(),@actor,@evidence)",workerId,c=>{Add(c,"id",id);Add(c,"policy",policyId);Add(c,"evidence",request.EvidenceReference);},t);await Audit("workforce.policy_acknowledged","PolicyAcknowledgement",id,t);return Created("",new{id});}catch(DbException){return Conflict(new{message="Policy is already acknowledged."});}}
 [HttpPost("care-workers/{workerId:guid}/employee-relations")][Authorize(Roles="CareManager,Administrator")]public async Task<IActionResult> EmployeeCase(Guid workerId,EmployeeCaseRequest request,CancellationToken t){if(!await Worker(workerId,t))return NotFound();if(request.CaseType is not("Disciplinary" or "Grievance")||string.IsNullOrWhiteSpace(request.Summary)||string.IsNullOrWhiteSpace(request.EvidenceReference))return BadRequest(new{message="Case type, summary and evidence are required."});var id=Guid.NewGuid();await Exec("insert into worker_employee_relations_cases(id,care_worker_id,organization_id,branch_id,case_type,status,summary,owner,evidence_reference,opened_at,created_by) values(@id,@worker,@organization,@branch,@type,'Open',@summary,@owner,@evidence,now(),@actor)",workerId,c=>{Add(c,"id",id);Add(c,"type",request.CaseType);Add(c,"summary",request.Summary);Add(c,"owner",request.Owner);Add(c,"evidence",request.EvidenceReference);},t);await Audit("workforce.employee_case_opened","EmployeeRelationsCase",id,t);return Created("",new{id});}
 [HttpPost("care-workers/{workerId:guid}/wellbeing")][Authorize(Roles="CareCoordinator,CareManager,Administrator")]public async Task<IActionResult> Wellbeing(Guid workerId,WellbeingRequest request,CancellationToken t){if(!await Worker(workerId,t))return NotFound();if(string.IsNullOrWhiteSpace(request.Summary)||string.IsNullOrWhiteSpace(request.Action)||string.IsNullOrWhiteSpace(request.EvidenceReference))return BadRequest(new{message="Summary, action and evidence are required."});var id=Guid.NewGuid();await Exec("insert into worker_wellbeing_records(id,care_worker_id,organization_id,branch_id,recorded_at,category,summary,action,owner,review_due,status,evidence_reference,created_by) values(@id,@worker,@organization,@branch,now(),@category,@summary,@action,@owner,@due,'Open',@evidence,@actor)",workerId,c=>{Add(c,"id",id);Add(c,"category",request.Category);Add(c,"summary",request.Summary);Add(c,"action",request.Action);Add(c,"owner",request.Owner);Add(c,"due",request.ReviewDue);Add(c,"evidence",request.EvidenceReference);},t);await Audit("workforce.wellbeing_recorded","WellbeingRecord",id,t);return Created("",new{id});}
 [HttpPost("care-workers/{workerId:guid}/requests")]public async Task<IActionResult> Request(Guid workerId,SelfServiceRequest request,CancellationToken t){if(!CanRead(workerId)||!await Worker(workerId,t))return NotFound();if(request.RequestType is not("Leave" or "Sickness" or "AvailabilityChange" or "EmploymentDetailChange")||string.IsNullOrWhiteSpace(request.Detail)||request.RequestType is "Leave" or "Sickness"&&(request.StartsAt is null||request.EndsAt<=request.StartsAt))return BadRequest(new{message="Request type, detail and a valid absence period are required."});var id=Guid.NewGuid();await Exec("insert into worker_self_service_requests(id,care_worker_id,organization_id,branch_id,request_type,starts_at,ends_at,detail,status,submitted_by) values(@id,@worker,@organization,@branch,@type,@starts,@ends,@detail,'Submitted',@actor)",workerId,c=>{Add(c,"id",id);Add(c,"type",request.RequestType);Add(c,"starts",request.StartsAt);Add(c,"ends",request.EndsAt);Add(c,"detail",request.Detail);},t);await Audit("workforce.self_service_submitted","WorkerSelfServiceRequest",id,t);return Created("",new{id});}
 [HttpPost("care-workers/{workerId:guid}/requests/{id:guid}/decide")][Authorize(Roles="CareManager,Administrator")]public async Task<IActionResult> Decide(Guid workerId,Guid id,SelfServiceDecision request,CancellationToken t){if(request.Decision is not("Approved" or "Rejected")||string.IsNullOrWhiteSpace(request.Reason))return BadRequest(new{message="Approval/rejection and a decision reason are required."});var changed=await Exec("update worker_self_service_requests set status=@decision,decision=@reason,decided_at=now(),decided_by=@actor where id=@id and care_worker_id=@worker and organization_id=@organization and branch_id=@branch and status='Submitted'",workerId,c=>{Add(c,"id",id);Add(c,"decision",request.Decision);Add(c,"reason",request.Reason);},t);if(changed==0)return Conflict(new{message="Only a submitted request can be decided."});await Audit("workforce.self_service_decided","WorkerSelfServiceRequest",id,t);return Ok(new{message="Request decision recorded."});}
 private bool CanRead(Guid id)=>user.IsBackOffice||user.IsAdministrator||user.IsCareManager||user.IsCareCoordinator||(user.IsCareWorker&&user.CareWorkerId==id);private Task<bool> Worker(Guid id,CancellationToken t)=>db.CareWorkers.AnyAsync(x=>x.Id==id&&x.OrganizationId==tenant.OrganizationId&&(tenant.IsOrganizationWide||x.BranchId==tenant.BranchId),t);private async Task<bool> CurrentCompetency(Guid worker,string skill,CancellationToken t)=>await Exists("select exists(select 1 from worker_competency_records where care_worker_id=@worker and organization_id=@organization and lower(competency)=lower(@skill) and status='Valid' and (expires_at is null or expires_at>now()))",worker,t,c=>Add(c,"skill",skill));private static object[] Alerts(List<Dictionary<string,object?>> restrictions,List<Dictionary<string,object?>> medication,List<Dictionary<string,object?>> policies,List<Dictionary<string,object?>> wellbeing){var now=DateTimeOffset.UtcNow;var values=new List<object>();values.AddRange(restrictions.Where(x=>x["status"]?.ToString()=="Active").Select(x=>(object)new{type="AssignmentRestricted",message=$"Active {x["restrictionType"]} restriction: {x["reason"]}"}));if(medication.FirstOrDefault() is { } med&&(med["status"]?.ToString()!="Authorized"||med["expiresAt"] is DateTimeOffset e&&e<=now.AddDays(30)))values.Add(new{type="MedicationAuthorization",message="Medication authorization is unavailable or due for renewal."});values.AddRange(policies.Where(x=>x["requiresAcknowledgement"] is true&&x["acknowledgedAt"] is null).Select(x=>(object)new{type="PolicyAcknowledgement",message=$"Policy acknowledgement required: {x["title"]} v{x["version"]}."}));values.AddRange(wellbeing.Where(x=>x["status"]?.ToString()=="Open"&&x["reviewDue"] is DateTime d&&d.Date<=DateTime.UtcNow.Date).Select(x=>(object)new{type="WellbeingReview",message=$"Wellbeing review is due: {x["category"]}."}));return values.ToArray();}
 private async Task<List<Dictionary<string,object?>>> Rows(string sql,Guid w,CancellationToken t){var l=new List<Dictionary<string,object?>>();await using var c=await Command(sql,w,t);await using var r=await c.ExecuteReaderAsync(t);while(await r.ReadAsync(t)){var x=new Dictionary<string,object?>();for(var i=0;i<r.FieldCount;i++)x[Camel(r.GetName(i))]=r.IsDBNull(i)?null:r.GetValue(i);l.Add(x);}return l;}private async Task<bool> Exists(string sql,Guid w,CancellationToken t,Action<DbCommand>? bind=null){await using var c=await Command(sql,w,t);bind?.Invoke(c);return Convert.ToBoolean(await c.ExecuteScalarAsync(t));}private async Task<int> Exec(string sql,Guid w,Action<DbCommand> bind,CancellationToken t){await using var c=await Command(sql,w,t);bind(c);return await c.ExecuteNonQueryAsync(t);}private async Task<DbCommand> Command(string sql,Guid w,CancellationToken t){var cn=db.Database.GetDbConnection();if(cn.State!=ConnectionState.Open)await cn.OpenAsync(t);var c=cn.CreateCommand();c.CommandText=sql;Add(c,"worker",w);Add(c,"organization",tenant.OrganizationId);Add(c,"branch",tenant.BranchId??TenantDefaults.BranchId);Add(c,"actor",user.UserName);return c;}private async Task Audit(string a,string e,Guid id,CancellationToken t){db.AuditEvents.Add(new AuditEvent(Guid.NewGuid(),a,user.UserName,e,id,DateTimeOffset.UtcNow,tenant.OrganizationId,tenant.BranchId??TenantDefaults.BranchId));await db.SaveChangesAsync(t);}private static void Add(DbCommand c,string n,object? v){if(c.Parameters.Contains(n))return;var p=c.CreateParameter();p.ParameterName=n;p.Value=v??DBNull.Value;c.Parameters.Add(p);}private static string Camel(string v){var p=v.Split('_');return p[0]+string.Concat(p.Skip(1).Select(x=>char.ToUpperInvariant(x[0])+x[1..]));}
}
public sealed record RestrictionRequest(string RestrictionType,string Skill,string Reason,string EvidenceReference,DateTimeOffset StartsAt,DateTimeOffset? EndsAt);public sealed record MedicationAuthorizationRequest(string Status,string Scope,string EvidenceReference,DateTimeOffset? ExpiresAt,string Reason);public sealed record PolicyRequest(string Title,string Version,string ContentReference,bool RequiresAcknowledgement,bool OrganizationWide);public sealed record AcknowledgeRequest(string EvidenceReference);public sealed record EmployeeCaseRequest(string CaseType,string Summary,string Owner,string EvidenceReference);public sealed record WellbeingRequest(string Category,string Summary,string Action,string Owner,DateOnly? ReviewDue,string EvidenceReference);public sealed record SelfServiceRequest(string RequestType,DateTimeOffset? StartsAt,DateTimeOffset? EndsAt,string Detail);public sealed record SelfServiceDecision(string Decision,string Reason);
